import { useEffect, useMemo, useState } from 'react';
import { ArrowDownToLine, Check, ChevronRight, Play, RotateCcw, Search } from 'lucide-react';
import type { AdvancedDemoProps } from './types';
import { accessibleDocuments, bestCostThreshold, classificationMetrics, CONTRACT_DOCUMENTS, contractFindings, createMLDataset, evaluateResearch, extractObligations, fitML, initialMastery, LESSONS, lineDiff, masteryScore, planLearning, populationStability, predictML, RESEARCH_DOCUMENTS, researchClaims, researchConflicts, rocCurve, searchResearch, updateMastery, validISODate, type ContractDocument, type MLConfig, type MLDataset, type MLModel, type ResearchDocument, type ResearchRole } from './intelligenceEngine';
import './advanced-intelligence.css';

type Locale = 'zh' | 'en';
type Props = { locale: Locale };
const pct = (n: number) => `${(n * 100).toFixed(1)}%`;
const tr = (locale: Locale) => (zh: string, en: string) => locale === 'zh' ? zh : en;
function Tabs({ items, value, onChange }: { items: [string, string][]; value: string; onChange: (id: string) => void }) { return <nav className="adv-intel-tabs" aria-label="Workspace views">{items.map(([id, label]) => <button type="button" key={id} aria-pressed={id === value} onClick={() => onChange(id)}>{label}</button>)}</nav>; }
function Metrics({ items }: { items: [string, string | number, string][] }) { return <div className="adv-intel-metrics">{items.map(([label, value, sub]) => <div key={label}><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>)}</div>; }
function Empty({ children }: { children: React.ReactNode }) { return <div className="adv-intel-empty">{children}</div>; }
function Header({ brand, title, note, reset, locale }: { brand: string; title: string; note: string; reset: () => void; locale: Locale }) { return <><header className="adv-intel-header"><div><span className="adv-intel-brand">{brand}</span><h3>{title}</h3></div><button type="button" className="adv-intel-quiet" onClick={reset}><RotateCcw size={14} />{tr(locale)('重置系统', 'Reset system')}</button></header><p className="adv-intel-disclosure">{note}</p></>; }
function exportJSON(name: string, value: unknown) { const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); }

function ResearchAtlas({ locale }: Props) {
  const t = tr(locale);
  const [documents, setDocuments] = useState<ResearchDocument[]>(() => RESEARCH_DOCUMENTS.map(document => ({ ...document })));
  const [view, setView] = useState('search'); const [role, setRole] = useState<ResearchRole>('researcher'); const [history, setHistory] = useState(false);
  const [query, setQuery] = useState(t('循环寿命', 'cycle life')); const [weight, setWeight] = useState(2); const [k1, setK1] = useState(1.2);
  const [selected, setSelected] = useState('BAT-01@2'); const [draft, setDraft] = useState(''); const [draftKey, setDraftKey] = useState(''); const [focus, setFocus] = useState(-1); const [notice, setNotice] = useState(''); const [entity, setEntity] = useState('CELL-A');
  const visible = useMemo(() => accessibleDocuments(documents, role, history), [documents, role, history]);
  const selectedDocument = visible.find(document => `${document.id}@${document.version}` === selected) ?? visible[0];
  const sourceKey = `${selectedDocument.id}@${selectedDocument.version}:${locale}`;
  const visibleDraft = draftKey === sourceKey ? draft : selectedDocument.body[locale];
  useEffect(() => { setDraft(selectedDocument.body[locale]); setDraftKey(sourceKey); setNotice(''); }, [selectedDocument, locale, sourceKey]);
  const hits = searchResearch(visible, query, locale, weight, k1); const conflicts = researchConflicts(visible, locale); const entities = [...new Set(visible.flatMap(document => document.entities))];
  const baseline = evaluateResearch(visible, locale, 2, 1.2), evaluation = evaluateResearch(visible, locale, weight, k1);
  const openSource = (document: ResearchDocument, index = -1) => { setSelected(`${document.id}@${document.version}`); setFocus(index); setView('documents'); };
  const reset = () => { setDocuments(RESEARCH_DOCUMENTS.map(document => ({ ...document }))); setRole('researcher'); setHistory(false); setQuery(t('循环寿命', 'cycle life')); setWeight(2); setK1(1.2); setSelected('BAT-01@2'); setView('search'); setFocus(-1); setNotice(''); };
  const save = () => {
    if (!visibleDraft.trim() || visibleDraft === selectedDocument.body[locale]) { setNotice(t('正文为空或没有修改，未创建版本。', 'Empty or unchanged text; no version created.')); return; }
    const version = Math.max(...documents.filter(document => document.id === selectedDocument.id).map(document => document.version)) + 1;
    const next = { ...selectedDocument, version, body: { ...selectedDocument.body, [locale]: visibleDraft.slice(0, 12000) } };
    setDocuments(current => [...current, next]); setSelected(`${next.id}@${version}`); setFocus(-1); setNotice(t('已追加新版本，原版本仍保留。', 'New revision appended; previous versions are retained.'));
  };
  return <section className="adv-intel adv-intel-research">
    <Header brand="ATLAS / RESEARCH INTELLIGENCE" title={t('证据先行，结论有据', 'Evidence before conclusions')} note={t('合成研发证据 · 分段 BM25 与显式声明规则 · 无模型推理 · 访问角色仅模拟可见性', 'Synthetic research evidence · Passage BM25 and explicit claim rules · No model reasoning · Roles simulate visibility')} reset={reset} locale={locale} />
    <div className="adv-intel-toolbar"><label>{t('访问视角', 'Access view')}<select value={role} onChange={event => setRole(event.target.value as ResearchRole)}><option value="reader">{t('公开读者', 'Public reader')}</option><option value="researcher">{t('研发成员', 'Research member')}</option><option value="lead">{t('研发负责人', 'Research lead')}</option></select></label><label className="adv-intel-check"><input type="checkbox" checked={history} onChange={event => setHistory(event.target.checked)} />{t('纳入可见历史版本', 'Include visible historical revisions')}</label><span className="adv-intel-pill">{t('索引前过滤', 'Filtered before indexing')}</span></div>
    <Metrics items={[[t('可见文档版本', 'Visible revisions'), visible.length, t('默认最新版本', 'Latest by default')], [t('证据段落', 'Evidence passages'), visible.reduce((sum, document) => sum + document.body[locale].split(/\n\s*\n/).length, 0), 'BM25'], [t('声明值差异', 'Claim differences'), conflicts.length, t('人工复核，不判真假', 'Human review; no truth judgment')], [t('关联实体', 'Linked entities'), entities.length, t('显式来源关系', 'Explicit provenance')]]} />
    <Tabs value={view} onChange={setView} items={[["search", t('证据检索', 'Search')], ['graph', t('实体地图', 'Entity map')], ['conflicts', t('声明复核', 'Claim review')], ['evaluation', t('查询评测', 'Evaluation')], ['documents', t('版本资料室', 'Versions')]]} />
    {view === 'search' && <div className="adv-intel-grid"><aside className="adv-intel-panel"><h4>{t('检索实验', 'Retrieval experiment')}</h4><label>{t('标题权重', 'Title weight')}<strong>{weight.toFixed(1)}</strong><input type="range" min="0" max="5" step="0.5" value={weight} onChange={event => setWeight(Number(event.target.value))} /></label><label>BM25 k1<strong>{k1.toFixed(1)}</strong><input type="range" min="0.1" max="3" step="0.1" value={k1} onChange={event => setK1(Number(event.target.value))} /></label><p className="adv-intel-note">{t('中文相邻双字 / 英文词项。分段长度归一化 b=0.75。分数是排序值，不是正确概率。', 'Chinese bigrams / English words. Length normalization b=0.75. Scores rank matches; they are not truth probabilities.')}</p><h5>{t('可见语料', 'Visible corpus')}</h5>{visible.map(document => <button key={`${document.id}@${document.version}`} className="adv-intel-source-button" type="button" onClick={() => openSource(document)}><span>{document.title[locale]}</span><small>{document.id} · v{document.version}</small></button>)}</aside><div className="adv-intel-panel"><label className="adv-intel-search"><Search size={16} /><input aria-label={t('检索研发证据', 'Search research evidence')} value={query} onChange={event => setQuery(event.target.value)} maxLength={200} /></label><p className="adv-intel-note" role="status">{hits.length} {t('个匹配段落', 'matching passages')}</p><div className="adv-intel-results">{hits.length ? hits.map(hit => <article key={hit.key}><div><button type="button" onClick={() => openSource(hit.document, hit.index)}>{hit.key}</button><strong>{hit.score.toFixed(3)}</strong></div><h5>{hit.document.title[locale]}</h5><p>{hit.text}</p><footer>{hit.document.entities.join(' / ')}</footer></article>) : <Empty>{t('没有可见来源命中。更换关键词或访问视角。', 'No visible sources match. Try another term or access view.')}</Empty>}</div></div></div>}
    {view === 'graph' && <div className="adv-intel-panel"><h4>{t('文档 → 实体：显式证据关系', 'Documents → entities: explicit provenance')}</h4><svg className="adv-intel-entity-graph" viewBox={`0 0 700 ${Math.max(280, entities.length * 33, visible.length * 37 + 20)}`} role="img" aria-label={t('文档与实体关联图', 'Document-to-entity graph')}>{visible.flatMap((document, i) => document.entities.map(name => <line key={`${document.id}-${document.version}-${name}`} x1="225" y1={28 + i * 37} x2="480" y2={25 + entities.indexOf(name) * 33} stroke={name === entity ? '#40948c' : '#d8e6e1'} strokeWidth={name === entity ? 2 : 1} />))}{visible.map((document, i) => <g key={`${document.id}@${document.version}`}><rect x="10" y={12 + i * 37} width="215" height="29" rx="6" fill="#e8f1ed" /><text x="20" y={31 + i * 37}>{document.id}@{document.version} · {document.title[locale].slice(0, 18)}</text></g>)}{entities.map((name, i) => <g key={name}><circle cx="480" cy={25 + i * 33} r="5" fill={name === entity ? '#30796d' : '#9cbeb1'} /><text x="495" y={29 + i * 33}>{name}</text></g>)}</svg><div className="adv-intel-chips">{entities.map(name => <button type="button" key={name} aria-pressed={entity === name} onClick={() => setEntity(name)}>{name}</button>)}</div><div className="adv-intel-linked-sources">{visible.filter(document => document.entities.includes(entity)).map(document => <button type="button" key={`${document.id}@${document.version}`} onClick={() => openSource(document)}>{document.title[locale]} <ChevronRight size={14} /></button>)}</div></div>}
    {view === 'conflicts' && <div className="adv-intel-panel"><h4>{t('同一声明键，不同来源值', 'Same claim key, different source values')}</h4><p className="adv-intel-note">{t('来自 [claim:key=value] 标记。协议、样本和时间可能不同；这里只标差异，不能自动裁定冲突。', 'From [claim:key=value] tags. Protocols, samples and dates may differ; this flags differences, not adjudicated contradictions.')}</p>{conflicts.length ? conflicts.map(group => <article className="adv-intel-conflict" key={group.key}><h5>{group.key}</h5>{group.claims.map(claim => <div key={`${claim.source}:${claim.value}`}><strong>{claim.value}</strong><button type="button" onClick={() => openSource(claim.document)}>{claim.source}</button></div>)}</article>) : <Empty>{t('当前可见版本没有同键不同值。', 'No same-key value differences in visible revisions.')}</Empty>}<p className="adv-intel-note">{researchClaims(visible, locale).length} {t('条显式声明已检查', 'explicit claims checked')}</p></div>}
    {view === 'evaluation' && <div className="adv-intel-panel"><h4>{t('五条固定查询：比较权重配置', 'Five fixed queries: compare configurations')}</h4><div className="adv-intel-toolbar"><label>{t('B 标题权重', 'B title weight')}<input type="number" min="0" max="5" step="0.5" value={weight} onChange={event => setWeight(Math.max(0, Math.min(5, Number(event.target.value))))} /></label><label>B k1<input type="number" min="0.1" max="3" step="0.1" value={k1} onChange={event => setK1(Math.max(0.1, Math.min(3, Number(event.target.value))))} /></label><span className="adv-intel-note">A: title 2 / k1 1.2 · top 5 {t('段落后去重来源', 'passages, then unique sources')}</span></div><div className="adv-intel-table-wrap"><table><thead><tr><th>{t('查询 / 期望可见源', 'Query / expected visible sources')}</th><th>A recall</th><th>B recall</th><th>B precision</th><th>{t('B实际来源', 'B actual sources')}</th></tr></thead><tbody>{evaluation.map((row, i) => <tr key={row.query.en}><td>{row.query[locale]}<small>{row.expected.join(', ') || '∅'}</small></td><td>{row.unavailable ? 'N/A' : pct(baseline[i].recall)}</td><td>{row.unavailable ? 'N/A' : pct(row.recall)}</td><td>{row.unavailable ? 'N/A' : pct(row.precision)}</td><td>{row.actual.join(', ') || '∅'}</td></tr>)}</tbody></table></div><p className="adv-intel-note">{t('不可见的金标来源不参与评测。N/A 不是通过；空结果负查询必须确实不命中。此小查询集不能代表企业检索质量。', 'Hidden gold sources are excluded. N/A is not a pass; negative queries must actually return no matches. This small suite does not represent enterprise retrieval quality.')}</p></div>}
    {view === 'documents' && <div className="adv-intel-grid"><aside className="adv-intel-panel">{visible.map(document => <button type="button" className="adv-intel-source-button" key={`${document.id}@${document.version}`} aria-pressed={document === selectedDocument} onClick={() => { setSelected(`${document.id}@${document.version}`); setFocus(-1); }}><span>{document.title[locale]}</span><small>{document.id}@{document.version}</small></button>)}</aside><div className="adv-intel-panel"><h4>{selectedDocument.title[locale]} <span className="adv-intel-pill">v{selectedDocument.version}</span></h4><div className="adv-intel-source-passages">{selectedDocument.body[locale].split(/\n\s*\n/).map((text, i) => <p key={i} className={i === focus ? 'adv-intel-highlight' : ''}><small>§{i + 1}</small>{text}</p>)}</div><label>{t('编辑当前语言正文 · 保存为新版本', 'Edit current-language text · save a new revision')}<textarea rows={9} maxLength={12000} value={visibleDraft} onChange={event => { setDraftKey(sourceKey); setDraft(event.target.value); }} /></label><button type="button" className="adv-intel-primary" onClick={save} disabled={documents.length >= 40}>{t('创建新版本并重建索引', 'Create revision and reindex')}</button><p className="adv-intel-note" role="status">{notice || t('最多40个版本。编辑只更新当前语言，不自动翻译。', 'Up to 40 revisions. Edits update this language only, with no automatic translation.')}</p></div></div>}
  </section>;
}

type Experiment = { id: string; model: MLModel; dataset: MLDataset; validationLoss: number };
function ModelFoundry({ locale }: Props) {
  const t = tr(locale); const [view, setView] = useState('experiments'); const [version, setVersion] = useState<'v1' | 'v2'>('v1'); const [noise, setNoise] = useState(0.08);
  const data = useMemo(() => createMLDataset(version, noise), [version, noise]); const [algorithm, setAlgorithm] = useState<MLConfig['algorithm']>('logistic'); const [rate, setRate] = useState(0.25); const [epochs, setEpochs] = useState(120); const [regularization, setRegularization] = useState(0.01);
  const [runs, setRuns] = useState<Experiment[]>([]); const [selected, setSelected] = useState(''); const [threshold, setThreshold] = useState(0.5); const [fpCost, setFpCost] = useState(1); const [fnCost, setFnCost] = useState(5); const [tested, setTested] = useState(false); const [shift, setShift] = useState(0.4); const [registry, setRegistry] = useState<{ name: string; run: Experiment; threshold: number; tested: boolean }[]>([]);
  useEffect(() => { setRuns([]); setSelected(''); setTested(false); }, [data]);
  const active = runs.find(run => run.id === selected && run.dataset === data); const predictions = active ? data.validation.map(point => predictML(active.model, point)) : []; const labels = data.validation.map(point => point.label); const metrics = classificationMetrics(predictions, labels, threshold); const roc = rocCurve(predictions, active ? labels : []); const costBest = bestCostThreshold(predictions, active ? labels : [], fpCost, fnCost);
  const train = (sweep: boolean) => {
    const configs: MLConfig[] = sweep ? [...[0.08, 0.25, 0.7].map(rate => ({ algorithm: 'logistic' as const, rate, epochs, regularization })), ...[0, 0.1, 0.6].map(regularization => ({ algorithm: 'stump' as const, rate, epochs, regularization }))] : [{ algorithm, rate, epochs, regularization }];
    const next = configs.map((config, i) => { const model = fitML(data.train, config); return { id: `RUN-${String(Math.max(0, ...runs.map(run => Number(run.id.slice(4)))) + i + 1).padStart(3, '0')}`, model, dataset: data, validationLoss: classificationMetrics(data.validation.map(point => predictML(model, point)), labels).loss }; });
    setRuns(previous => [...previous, ...next].slice(-60)); setSelected([...next].sort((a, b) => a.validationLoss - b.validationLoss)[0].id); setTested(false); setView('experiments');
  };
  const testMetrics = active && tested ? classificationMetrics(data.test.map(point => predictML(active.model, point)), data.test.map(point => point.label), threshold) : null;
  const setThresholdClean = (value: number) => { setThreshold(value); setTested(false); };
  const reset = () => { setVersion('v1'); setNoise(0.08); setRuns([]); setSelected(''); setThreshold(0.5); setRegistry([]); setTested(false); setRate(0.25); setEpochs(120); setRegularization(0.01); setAlgorithm('logistic'); setFpCost(1); setFnCost(5); setShift(0.4); setView('experiments'); };
  const chart = (values: number[]) => values.map((value, i) => `${i ? 'L' : 'M'}${20 + i / Math.max(1, values.length - 1) * 350},${140 - value / Math.max(0.8, ...values) * 115}`).join(' ');
  return <section className="adv-intel adv-intel-foundry"><Header brand="FOUNDRY / EXPERIMENT OPERATIONS" title={t('每个模型，都留下实验依据', 'An evidence trail for every model')} note={t('合成工业负载 · 真实双算法训练 · 三集隔离 · 本地登记，不是云端训练或部署', 'Synthetic industrial load · Two real algorithms · Three disjoint splits · Local registry, no cloud training or deployment')} reset={reset} locale={locale} />
    <Metrics items={[[t('训练 / 验证 / 测试', 'Train / validation / test'), '216 / 72 / 72', `${version} · ${t('固定种子', 'fixed seed')}`], [t('已运行实验', 'Computed experiments'), runs.length, t('按验证损失比较', 'Compare validation loss')], [t('当前验证 AUC', 'Current validation AUC'), roc.auc === null ? '—' : roc.auc.toFixed(3), t('不是测试集指标', 'Not a test-set metric')], [t('本地模型版本', 'Local model versions'), registry.length, t('当前案例会话', 'Current case session')]]} />
    <Tabs value={view} onChange={setView} items={[["data", t('数据版本', 'Data versions')], ['experiments', t('实验扫描', 'Experiments')], ['evaluation', t('评测与成本', 'Evaluation / cost')], ['drift', t('分布漂移', 'Distribution drift')], ['registry', t('模型登记', 'Registry')]]} />
    {view === 'data' && <div className="adv-intel-panel"><div className="adv-intel-toolbar"><label>{t('数据版本', 'Dataset version')}<select value={version} onChange={event => setVersion(event.target.value as 'v1' | 'v2')}><option value="v1">v1 · {t('基准线性负载', 'baseline linear load')}</option><option value="v2">v2 · {t('均值与决策规则变化', 'shifted mean and decision rule')}</option></select></label><label>{t('标签噪声', 'Label noise')}<input type="range" min="0" max="0.3" step="0.01" value={noise} onChange={event => setNoise(Number(event.target.value))} /><strong>{pct(noise)}</strong></label></div><p className="adv-intel-note">{t('更换数据清空当前实验，不删除已登记快照。测试样本不参与拟合、扫描排名或阈值优化。', 'Changing data clears current runs but preserves registry snapshots. Test samples never influence fitting, sweep ranking or threshold optimization.')}</p><div className="adv-intel-split-bars">{(['train', 'validation', 'test'] as const).map(split => <div key={split}><strong>{split.toUpperCase()}</strong><span>{data[split].length} / 360</span><progress value={data[split].length} max={360} /><small>{data[split][0].id} → {data[split].at(-1)!.id}</small></div>)}</div><div className="adv-intel-table-wrap"><table><thead><tr><th>ID</th><th>CPU feature</th><th>Queue feature</th><th>{t('训练标签', 'Training label')}</th></tr></thead><tbody>{data.train.slice(0, 12).map(point => <tr key={point.id}><td>{point.id}</td><td>{point.x.toFixed(4)}</td><td>{point.y.toFixed(4)}</td><td>{point.label}</td></tr>)}</tbody></table></div></div>}
    {view === 'experiments' && <div className="adv-intel-grid"><aside className="adv-intel-panel"><h4>{t('实验配置', 'Experiment configuration')}</h4><label>{t('算法', 'Algorithm')}<select value={algorithm} onChange={event => setAlgorithm(event.target.value as MLConfig['algorithm'])}><option value="logistic">Logistic regression</option><option value="stump">Decision stump</option></select></label><label>{t('学习率 · 仅逻辑回归', 'Learning rate · logistic only')}<strong>{rate}</strong><input type="range" min="0.01" max="1" step="0.01" disabled={algorithm === 'stump'} value={rate} onChange={event => setRate(Number(event.target.value))} /></label><label>{t('轮数 · 仅逻辑回归', 'Epochs · logistic only')}<strong>{epochs}</strong><input type="range" min="20" max="300" step="20" disabled={algorithm === 'stump'} value={epochs} onChange={event => setEpochs(Number(event.target.value))} /></label><label>{t('L2 / 树桩叶子平滑', 'L2 / stump leaf smoothing')}<strong>{regularization.toFixed(2)}</strong><input type="range" min="0" max="0.6" step="0.01" value={regularization} onChange={event => setRegularization(Number(event.target.value))} /></label><button type="button" className="adv-intel-primary" onClick={() => train(false)}><Play size={14} />{t('训练当前配置', 'Train configuration')}</button><button type="button" className="adv-intel-secondary" onClick={() => train(true)}>{t('扫描六组配置', 'Sweep six configurations')}</button><p className="adv-intel-note">{t('扫描：3个逻辑回归学习率与3个树桩平滑参数。默认选择验证loss最低者。', 'Sweep: three logistic learning rates and three stump smoothing parameters. Select the lowest validation loss.')}</p></aside><div className="adv-intel-panel"><h4>{t('实验排行榜 · 验证 loss', 'Experiment ranking · validation loss')}</h4>{runs.length ? <><div className="adv-intel-table-wrap"><table><thead><tr><th>Run</th><th>Algorithm</th><th>lr / L2</th><th>Val loss</th></tr></thead><tbody>{[...runs].sort((a, b) => a.validationLoss - b.validationLoss).map(run => <tr key={run.id} className={selected === run.id ? 'adv-intel-row-active' : ''}><td><button type="button" onClick={() => { setSelected(run.id); setTested(false); }}>{run.id}</button></td><td>{run.model.config.algorithm}</td><td>{run.model.config.algorithm === 'stump' ? '—' : run.model.config.rate} / {run.model.config.regularization}</td><td>{run.validationLoss.toFixed(4)}</td></tr>)}</tbody></table></div>{active && <figure><figcaption>{active.id} · {t('真实训练交叉熵', 'computed training cross entropy')}</figcaption><svg viewBox="0 0 400 165" role="img" aria-label={t('实际训练损失曲线', 'Computed training loss curve')}><path d={chart(active.model.history)} fill="none" stroke="#8570bf" strokeWidth="3" /><text x="20" y="160">0</text><text x="300" y="160">{active.model.history.length - 1} {t('更新', 'updates')}</text></svg><p className="adv-intel-note">{active.model.history[0].toFixed(4)} → {active.model.history.at(-1)!.toFixed(4)} · {active.model.config.algorithm === 'stump' ? t('树桩为一次穷举拟合，不伪造逐轮曲线。', 'A stump uses one split-search fit, not artificial epochs.') : `w = [${active.model.weights.map(value => value.toFixed(3)).join(', ')}]`}</p></figure>}</> : <Empty>{t('运行训练或六组扫描，生成真实实验结果。', 'Train or sweep six configurations to compute experiment results.')}</Empty>}</div></div>}
    {view === 'evaluation' && (active ? <div className="adv-intel-grid"><aside className="adv-intel-panel"><h4>{active.id} / {t('验证集决策', 'Validation decisions')}</h4><label>{t('分类阈值', 'Classification threshold')}<strong>{threshold.toFixed(3)}</strong><input type="range" min="0" max="1" step="0.01" value={Math.min(1, threshold)} onChange={event => setThresholdClean(Number(event.target.value))} /></label><label>{t('误报成本 FP', 'False-positive cost')}<input type="number" min="0" max="100" value={fpCost} onChange={event => setFpCost(Math.max(0, Math.min(100, Number(event.target.value))))} /></label><label>{t('漏报成本 FN', 'False-negative cost')}<input type="number" min="0" max="100" value={fnCost} onChange={event => setFnCost(Math.max(0, Math.min(100, Number(event.target.value))))} /></label><button type="button" className="adv-intel-secondary" onClick={() => setThresholdClean(costBest.threshold)}>{t('使用验证集最低成本阈值', 'Use validation minimum-cost threshold')}</button><p className="adv-intel-note">{t('当前成本', 'Current cost')}: {metrics.fp * fpCost + metrics.fn * fnCost} · {t('最低可达', 'Minimum')}: {costBest.cost}</p><button type="button" className="adv-intel-primary" onClick={() => setTested(true)} disabled={tested}>{t('显式评估隔离测试集', 'Evaluate isolated test split')}</button><p className="adv-intel-note">{t('每次调阈值或换模型需重新确认测试。多次查看测试结果仍可能导致人工调参泄漏。', 'Changing threshold or model requires a fresh test action. Repeated inspection can still create human tuning leakage.')}</p></aside><div className="adv-intel-panel"><h4>{t('验证混淆矩阵与 ROC', 'Validation confusion matrix and ROC')}</h4><div className="adv-intel-confusion"><div>TN<strong>{metrics.tn}</strong></div><div>FP<strong>{metrics.fp}</strong></div><div>FN<strong>{metrics.fn}</strong></div><div>TP<strong>{metrics.tp}</strong></div></div><p className="adv-intel-note">Accuracy {pct(metrics.accuracy)} · Precision {pct(metrics.precision)} · Recall {pct(metrics.recall)}</p><svg className="adv-intel-roc" viewBox="0 0 300 200" role="img" aria-label="Validation ROC curve"><path d="M25 170 L270 20" stroke="#d6d0e4" strokeDasharray="4 4" /><path d={roc.points.map((point, i) => `${i ? 'L' : 'M'}${25 + point.fpr * 245},${170 - point.tpr * 150}`).join(' ')} fill="none" stroke="#8570bf" strokeWidth="3" /><text x="25" y="190">FPR 0</text><text x="245" y="190">1</text><text x="5" y="20">TPR</text><text x="160" y="45">AUC {roc.auc?.toFixed(3) ?? 'N/A'}</text></svg>{testMetrics ? <div className="adv-intel-callout" role="status"><strong>{t('隔离测试集 · 72样本', 'Isolated test · 72 samples')}</strong><p>loss {testMetrics.loss.toFixed(4)} · accuracy {pct(testMetrics.accuracy)} · FP {testMetrics.fp} / FN {testMetrics.fn}</p></div> : <p className="adv-intel-note">{t('测试指标尚未计算。', 'Test metrics have not been computed.')}</p>}<button type="button" className="adv-intel-secondary" onClick={() => { setRegistry(items => [...items, { name: `MODEL-v${items.length + 1}`, run: active, threshold, tested }]); setView('registry'); }}>{t('登记当前模型卡', 'Register current model card')}</button></div></div> : <Empty>{t('先训练一个模型。', 'Train a model first.')}</Empty>)}
    {view === 'drift' && <div className="adv-intel-panel"><h4>{t('特征分布漂移实验', 'Feature distribution shift experiment')}</h4><label>{t('为当前 CPU 特征增加均值偏移', 'Add a mean shift to current CPU features')}<strong>{shift.toFixed(2)}</strong><input type="range" min="-1" max="1" step="0.05" value={shift} onChange={event => setShift(Number(event.target.value))} /></label><Metrics items={[[t('CPU PSI', 'CPU PSI'), populationStability(data.train.map(point => point.x), data.validation.map(point => point.x + shift)).toFixed(4), t('五分桶 + 0.5平滑', 'Five bins + 0.5 smoothing')], [t('队列 PSI', 'Queue PSI'), populationStability(data.train.map(point => point.y), data.validation.map(point => point.y)).toFixed(4), t('无人工偏移', 'No injected shift')]]} /><div className="adv-intel-histograms">{[-0.6, -0.2, 0.2, 0.6, Infinity].map((upper, i) => { const lower = [-Infinity, -0.6, -0.2, 0.2, 0.6][i]; const ref = data.train.filter(point => point.x > lower && point.x <= upper).length / data.train.length; const shifted = data.validation.filter(point => point.x + shift > lower && point.x + shift <= upper).length / data.validation.length; return <div key={i}><div><span style={{ height: `${ref * 180}px` }} /><span style={{ height: `${shifted * 180}px` }} /></div><small>{Number.isFinite(lower) ? lower : '−∞'}…{Number.isFinite(upper) ? upper : '∞'}</small></div>; })}</div><p className="adv-intel-note">{t('浅色：训练基准；深色：偏移后的验证特征。PSI只比较分布，不能证明模型性能变化或业务异常。', 'Light: training reference; dark: shifted validation features. PSI compares distributions and does not prove performance changes or business anomalies.')}</p></div>}
    {view === 'registry' && <div className="adv-intel-panel"><h4>{t('本地登记簿 / 模型卡', 'Local registry / model cards')}</h4>{registry.length ? registry.map(entry => <article className="adv-intel-model-card" key={entry.name}><div><strong>{entry.name}</strong><span className="adv-intel-pill">{entry.tested ? t('已显式测试', 'Explicitly tested') : t('仅验证集', 'Validation only')}</span></div><p>{entry.run.id} · {entry.run.model.config.algorithm} · dataset {entry.run.dataset.version} · threshold {entry.threshold.toFixed(3)}</p><p>Validation loss {entry.run.validationLoss.toFixed(4)} · {t('训练样本', 'Training samples')} {entry.run.dataset.train.length}</p><details><summary>{t('检查真实参数和数据划分', 'Inspect actual parameters and split IDs')}</summary><pre>{JSON.stringify({ dataVersion: entry.run.dataset.version, seed: entry.run.dataset.seed, labelNoise: entry.run.dataset.noise, configuration: entry.run.model.config, parameters: entry.run.model.config.algorithm === 'logistic' ? entry.run.model.weights : entry.run.model.stump, split: { train: entry.run.dataset.train.length, validation: entry.run.dataset.validation.length, test: entry.run.dataset.test.length }, firstTrainingId: entry.run.dataset.train[0].id }, null, 2)}</pre></details></article>) : <Empty>{t('在评测页登记当前模型；登记保留快照，不会部署。', 'Register a model from Evaluation; registration preserves a snapshot and does not deploy.')}</Empty>}</div>}
  </section>;
}

function LearningCampus({ locale }: Props) {
  const t = tr(locale); const [view, setView] = useState('curriculum'); const [mastery, setMastery] = useState(initialMastery); const [completed, setCompleted] = useState(['basics']); const [selected, setSelected] = useState('python'); const [choice, setChoice] = useState<number | null>(null); const [submitted, setSubmitted] = useState(false); const [events, setEvents] = useState<{ id: string; correct: boolean; choice: number }[]>([]); const [goal, setGoal] = useState('capstone'); const [budget, setBudget] = useState(180); const [mentors, setMentors] = useState(1); const [reviewOnly, setReviewOnly] = useState(false);
  const lesson = LESSONS.find(item => item.id === selected)!; const unlocked = lesson.after.every(id => completed.includes(id));
  const mistakes = LESSONS.filter(item => [...events].reverse().find(event => event.id === item.id)?.correct === false);
  const plan = planLearning(LESSONS, completed, goal, budget, mentors, mastery);
  const recommendations = LESSONS.filter(item => !completed.includes(item.id) && item.after.every(id => completed.includes(id))).sort((a, b) => (1 - masteryScore(mastery, b.id)) * b.difficulty - (1 - masteryScore(mastery, a.id)) * a.difficulty);
  const open = (id: string) => { setSelected(id); setChoice(null); setSubmitted(false); setView('practice'); };
  const answer = () => { if (choice === null || submitted || !unlocked) return; const correct = choice === lesson.correct; const next = updateMastery(mastery, lesson.id, correct); setMastery(next); setSubmitted(true); setEvents(items => [...items, { id: lesson.id, correct, choice }]); if (correct && masteryScore(next, lesson.id) >= 0.65) setCompleted(items => [...new Set([...items, lesson.id])]); };
  const reset = () => { setMastery(initialMastery()); setCompleted(['basics']); setEvents([]); setSelected('python'); setChoice(null); setSubmitted(false); setGoal('capstone'); setBudget(180); setMentors(1); setView('curriculum'); setReviewOnly(false); };
  const positions: Record<string, [number, number]> = { basics: [45, 155], python: [200, 70], statistics: [200, 230], cleaning: [355, 50], visualization: [510, 270], regression: [510, 80], evaluation: [665, 65], ethics: [510, 190], clinic: [820, 120], capstone: [975, 155] };
  return <section className="adv-intel adv-intel-campus"><Header brand="CAMPUS / ADAPTIVE LEARNING" title={t('下一步学习，有清楚的理由', 'A clear reason for the next lesson')} note={t('合成课程与题库 · Beta掌握度是练习规则，不是正式测评 · 路径按先修、分钟和导师资源计算', 'Synthetic curriculum · Beta mastery is a practice rule, not formal assessment · Plans respect prerequisites, minutes and mentor resources')} reset={reset} locale={locale} />
    <Metrics items={[[t('完成课程', 'Completed lessons'), `${completed.length} / ${LESSONS.length}`, t('初始已完成数据素养', 'Data literacy initially complete')], [t('答题次数', 'Answer attempts'), events.length, t('真实交互累计', 'Counted from actual interactions')], [t('待复习错题', 'Mistakes to review'), mistakes.length, t('以每题最近答题为准', 'Latest answer per question')], [t('当前可解锁', 'Ready to learn'), recommendations.length, t('先修全部完成', 'All prerequisites complete')]]} />
    <Tabs value={view} onChange={setView} items={[["curriculum", t('课程地图', 'Curriculum')], ['practice', t('练习与错题', 'Practice / mistakes')], ['planner', t('路径规划', 'Path planner')], ['history', t('学习记录', 'Learning records')]]} />
    {view === 'curriculum' && <div className="adv-intel-panel"><h4>{t('数据技能先修网络', 'Data-skills prerequisite network')}</h4><div className="adv-intel-course-map"><svg viewBox="0 0 1100 330" role="img" aria-label={t('十门课程先修关系图', 'Ten-course prerequisite graph')}>{LESSONS.flatMap(item => item.after.map(prior => <path key={`${prior}-${item.id}`} d={`M${positions[prior][0] + 90} ${positions[prior][1]} C${positions[prior][0] + 140} ${positions[prior][1]},${positions[item.id][0] - 45} ${positions[item.id][1]},${positions[item.id][0]} ${positions[item.id][1]}`} fill="none" stroke={completed.includes(prior) ? '#b58d3b' : '#ded9c9'} strokeWidth="2" />))}{LESSONS.map(item => <g key={item.id}><rect x={positions[item.id][0]} y={positions[item.id][1] - 21} width="95" height="44" rx="7" fill={completed.includes(item.id) ? '#dce8cd' : item.after.every(id => completed.includes(id)) ? '#f2e1b4' : '#efeee7'} /><text x={positions[item.id][0] + 7} y={positions[item.id][1] - 2}>{item.title[locale].slice(0, locale === 'zh' ? 8 : 13)}</text><text x={positions[item.id][0] + 7} y={positions[item.id][1] + 13}>{item.minutes}m · {pct(masteryScore(mastery, item.id))}</text></g>)}</svg></div><div className="adv-intel-recommendations">{recommendations.map(item => <article key={item.id}><span className="adv-intel-pill">{t('现在可学', 'Ready now')}</span><h5>{item.title[locale]}</h5><p>{t('先修已完成；掌握度', 'Prerequisites complete; mastery')} {pct(masteryScore(mastery, item.id))} · {item.minutes} min</p><small>{t('排序效用', 'Ranking utility')}: {(1 - masteryScore(mastery, item.id)).toFixed(2)} × {item.difficulty}</small><button type="button" onClick={() => open(item.id)}>{t('开始练习', 'Start practice')}<ChevronRight size={14} /></button></article>)}</div><div className="adv-intel-table-wrap"><table><thead><tr><th>{t('课程', 'Lesson')}</th><th>{t('先修', 'Prerequisites')}</th><th>{t('掌握度', 'Mastery')}</th><th>{t('状态', 'Status')}</th></tr></thead><tbody>{LESSONS.map(item => <tr key={item.id}><td><button type="button" onClick={() => open(item.id)}>{item.title[locale]}</button></td><td>{item.after.join(', ') || '—'}</td><td><progress max="1" value={masteryScore(mastery, item.id)} /> {pct(masteryScore(mastery, item.id))}</td><td>{completed.includes(item.id) ? t('已完成', 'Complete') : item.after.every(id => completed.includes(id)) ? t('可学习', 'Ready') : t('先修未满足', 'Locked')}</td></tr>)}</tbody></table></div></div>}
    {view === 'practice' && <div className="adv-intel-grid"><aside className="adv-intel-panel"><label className="adv-intel-check"><input type="checkbox" checked={reviewOnly} onChange={event => setReviewOnly(event.target.checked)} />{t('只看错题', 'Mistakes only')}</label>{(reviewOnly ? mistakes : LESSONS).map(item => <button className="adv-intel-source-button" type="button" key={item.id} aria-pressed={item.id === selected} onClick={() => open(item.id)}><span>{item.title[locale]}</span><small>{pct(masteryScore(mastery, item.id))}</small></button>)}{reviewOnly && !mistakes.length && <p className="adv-intel-note">{t('当前没有待复习错题。', 'No mistakes awaiting review.')}</p>}</aside><div className="adv-intel-panel"><span className="adv-intel-pill">{lesson.id.toUpperCase()} · {lesson.minutes} MIN</span><h4>{lesson.title[locale]}</h4>{unlocked ? <><p className="adv-intel-question">{lesson.question[locale]}</p><div className="adv-intel-options">{lesson.choices.map((option, i) => <button type="button" key={i} disabled={submitted} aria-pressed={choice === i} className={submitted ? i === lesson.correct ? 'adv-intel-answer-correct' : choice === i ? 'adv-intel-answer-wrong' : '' : ''} onClick={() => setChoice(i)}><b>{String.fromCharCode(65 + i)}</b>{option[locale]}</button>)}</div><button type="button" className="adv-intel-primary" disabled={choice === null || submitted} onClick={answer}>{t('提交答案', 'Submit answer')}</button>{submitted && <div className="adv-intel-callout" role="status"><strong>{choice === lesson.correct ? t('回答正确', 'Correct') : t('需要再练习', 'More practice needed')}</strong><p>{lesson.explanation[locale]}</p><p>{t('当前掌握度', 'Current mastery')} {pct(masteryScore(mastery, lesson.id))} · {completed.includes(lesson.id) ? t('课程已完成，下游已解锁。', 'Lesson complete; downstream lessons unlocked.') : t('达到65%且答对后完成课程。', 'Complete after a correct answer with mastery at least 65%.')}</p><button type="button" className="adv-intel-secondary" onClick={() => { setChoice(null); setSubmitted(false); }}>{t('开始新的复习轮次', 'Begin a new review attempt')}</button></div>}</> : <Empty>{t('需先完成：', 'Complete first: ')}{lesson.after.filter(id => !completed.includes(id)).map(id => LESSONS.find(item => item.id === id)!.title[locale]).join(' / ')}</Empty>}<p className="adv-intel-note">{t('Beta先验(2,2)；正确 alpha+2，错误 beta+2。重复点击不能重复计分，重新练习是新轮次。', 'Beta prior (2,2); correct adds 2 to alpha, incorrect adds 2 to beta. Duplicate submission does not score again; retrying starts a new attempt.')}</p></div></div>}
    {view === 'planner' && <div className="adv-intel-grid"><aside className="adv-intel-panel"><h4>{t('规划约束', 'Planning constraints')}</h4><label>{t('学习目标', 'Learning goal')}<select value={goal} onChange={event => setGoal(event.target.value)}>{LESSONS.map(item => <option key={item.id} value={item.id}>{item.title[locale]}</option>)}</select></label><label>{t('可用分钟', 'Available minutes')}<strong>{budget}</strong><input type="range" min="0" max="420" step="15" value={budget} onChange={event => setBudget(Number(event.target.value))} /></label><label>{t('导师席位', 'Mentor slots')}<select value={mentors} onChange={event => setMentors(Number(event.target.value))}><option>0</option><option>1</option><option>2</option></select></label><p className="adv-intel-note">{t('枚举目标先修子集；效用=1+(1−掌握度)×难度，目标课程额外+10。先修、总分钟、导师资源都是硬约束。', 'Enumerate target prerequisite subsets. Utility=1+(1−mastery)×difficulty, plus 10 for the goal. Prerequisites, minutes and mentor slots are hard constraints.')}</p></aside><div className="adv-intel-panel"><h4>{plan.reachesGoal ? t('当前资源可达到目标', 'Goal is feasible') : t('资源不足，提供可行阶段计划', 'Limited resources: feasible partial plan')}</h4><p className="adv-intel-note" role="status">{plan.minutes}/{budget} min · {plan.mentorSlots}/{mentors} {t('导师席位', 'mentor slots')} · {t('全部待学先修总计', 'Total remaining prerequisites')} {plan.totalRequired} min</p>{plan.lessons.length ? <ol className="adv-intel-path">{plan.lessons.map(item => <li key={item.id}><strong>{item.title[locale]}</strong><span>{item.minutes} min · mentor {item.mentor}</span><small>{t('前置', 'After')}: {item.after.join(', ') || '—'}</small><button type="button" disabled={!item.after.every(id => completed.includes(id))} onClick={() => open(item.id)}>{t('进入练习', 'Practice')}</button></li>)}</ol> : <Empty>{completed.includes(goal) ? t('目标课程已完成。', 'Goal already completed.') : t('当前资源无法容纳下一门先修课。增加分钟或导师席位。', 'The next prerequisite does not fit. Increase time or mentor slots.')}</Empty>}{plan.remaining.length > 0 && <p className="adv-intel-note">{t('本次计划之外', 'Outside this plan')}: {plan.remaining.map(item => item.title[locale]).join(' / ')}</p>}</div></div>}
    {view === 'history' && <div className="adv-intel-panel"><h4>{t('实际答题事件', 'Actual answer events')}</h4>{events.length ? <div className="adv-intel-table-wrap"><table><thead><tr><th>#</th><th>{t('课程', 'Lesson')}</th><th>{t('答案', 'Answer')}</th><th>{t('结果', 'Result')}</th></tr></thead><tbody>{events.map((event, i) => <tr key={i}><td>{i + 1}</td><td>{LESSONS.find(item => item.id === event.id)!.title[locale]}</td><td>{String.fromCharCode(65 + event.choice)}</td><td>{event.correct ? t('正确', 'Correct') : t('错误 / 待复习', 'Incorrect / review')}</td></tr>)}</tbody></table></div> : <Empty>{t('完成一次练习后，记录会出现在这里。', 'Complete a practice attempt to create a record.')}</Empty>}<p className="adv-intel-note">{t('记录的是答题次数，不将按钮点击换算为实际学习时长。', 'These are answer attempts; button clicks are not converted into actual study time.')}</p></div>}
  </section>;
}

function ContractDesk({ locale }: Props) {
  const t = tr(locale); const [documents, setDocuments] = useState<ContractDocument[]>(() => CONTRACT_DOCUMENTS.map(document => ({ ...document }))); const [selected, setSelected] = useState('CT-201@2'); const [view, setView] = useState('obligations'); const [today, setToday] = useState('2026-10-01'); const [evidence, setEvidence] = useState<Set<string>>(() => new Set()); const [handling, setHandling] = useState<Record<string, { state: string; note: string }>>({}); const [draft, setDraft] = useState(''); const [notice, setNotice] = useState(''); const [focusLine, setFocusLine] = useState(0); const [reviews, setReviews] = useState<{ version: string; date: string; findings: number; recorded: number; evidence: number }[]>([]);
  const current = documents.find(document => `${document.id}@${document.version}` === selected)!; const prior = documents.filter(document => document.id === current.id && document.version < current.version).sort((a, b) => b.version - a.version)[0];
  useEffect(() => { setDraft(current.body); setNotice(''); }, [current]);
  const obligations = extractObligations(current); const findings = contractFindings(current, today, evidence); const differences = lineDiff(prior?.body ?? '', current.body);
  const labels: Record<string, string> = { 'missing-owner': t('缺少负责人', 'Missing owner'), 'invalid-date': t('日期无效', 'Invalid date'), overdue: t('已逾期且无证据', 'Overdue without evidence'), 'due-soon': t('七天内到期', 'Due within seven days'), 'invalid-amount': t('金额无效', 'Invalid amount') };
  const source = (line: number) => { setFocusLine(line); setView('documents'); };
  const save = () => { if (!draft.trim() || draft === current.body) { setNotice(t('正文为空或未修改，未创建版本。', 'Empty or unchanged text; no revision created.')); return; } if (draft.split('\n').length > 200) { setNotice(t('最多200行，以保证逐行比较可响应。', 'Limit 200 lines to keep comparison responsive.')); return; } const next = { ...current, version: Math.max(...documents.filter(document => document.id === current.id).map(document => document.version)) + 1, body: draft }; setDocuments(items => [...items, next]); setSelected(`${next.id}@${next.version}`); setFocusLine(0); };
  const reset = () => { setDocuments(CONTRACT_DOCUMENTS.map(document => ({ ...document }))); setSelected('CT-201@2'); setView('obligations'); setToday('2026-10-01'); setEvidence(new Set()); setHandling({}); setReviews([]); setNotice(''); setFocusLine(0); };
  return <section className="adv-intel adv-intel-contract"><Header brand="CLAUSE / DELIVERY ASSURANCE" title={t('让每项义务，都能回到证据', 'Every obligation links back to evidence')} note={t('合成合同教学示例 · 仅解析显式结构化条款 · 不构成法律意见 · 无真实提醒、签署或付款', 'Synthetic contract teaching example · Explicit structured clauses only · No legal advice, actual reminders, signing or payments')} reset={reset} locale={locale} />
    <div className="adv-intel-toolbar"><label>{t('合同 / 版本', 'Contract / version')}<select value={selected} onChange={event => { setSelected(event.target.value); setFocusLine(0); }}>{documents.map(document => <option key={`${document.id}@${document.version}`} value={`${document.id}@${document.version}`}>{document.id} · {document.title[locale]} · v{document.version}</option>)}</select></label><label>{t('模拟今天', 'Simulated today')}<input type="date" value={today} onChange={event => { if (validISODate(event.target.value)) setToday(event.target.value); }} /></label><span className="adv-intel-pill">{t('当前版本证据独立', 'Evidence scoped to revision')}</span></div>
    <Metrics items={[[t('结构化义务', 'Structured obligations'), obligations.length, t('含付款里程碑', 'Includes payment milestones')], [t('规则发现', 'Rule findings'), findings.length, t('不是法律判断', 'Not legal judgments')], [t('本版本已附证据', 'Evidence in this version'), obligations.filter(item => evidence.has(item.key)).length, t('示例交付记录', 'Sample completion records')], [t('已保存审阅', 'Saved reviews'), reviews.length, t('版本与日期快照', 'Version and date snapshots')]]} />
    <Tabs value={view} onChange={setView} items={[["obligations", t('履约日历', 'Obligations')], ['diff', t('版本差异', 'Version diff')], ['findings', t('规则发现', 'Rule findings')], ['documents', t('证据与正文', 'Evidence / text')], ['reviews', t('审阅与导出', 'Review / export')]]} />
    {view === 'obligations' && <div className="adv-intel-panel"><h4>{current.title[locale]}</h4><div className="adv-intel-table-wrap"><table><thead><tr><th>ID / {t('交付', 'Deliverable')}</th><th>{t('负责人', 'Owner')}</th><th>{t('截止日', 'Due')}</th><th>{t('来源', 'Source')}</th><th>{t('交付证据', 'Delivery evidence')}</th></tr></thead><tbody>{[...obligations].sort((a, b) => a.due.localeCompare(b.due)).map(item => <tr key={item.key}><td><strong>{item.id} · {item.kind}</strong><small>{item.description}</small></td><td>{item.owner || '—'}</td><td className={!item.validDate || item.due < today && !evidence.has(item.key) ? 'adv-intel-danger-text' : ''}>{item.due || '—'}</td><td><button type="button" onClick={() => source(item.line)}>L{item.line}</button></td><td><button type="button" className="adv-intel-small-button" aria-pressed={evidence.has(item.key)} onClick={() => setEvidence(previous => { const next = new Set(previous); if (next.has(item.key)) next.delete(item.key); else next.add(item.key); return next; })}>{evidence.has(item.key) ? t('已附示例证据', 'Sample evidence attached') : t('附示例证据', 'Attach sample evidence')}</button></td></tr>)}</tbody></table></div>{!obligations.length && <Empty>{t('没有可解析的 OBL / PAY 行。查看正文格式说明。', 'No parseable OBL / PAY records. See the text-format guide.')}</Empty>}<p className="adv-intel-note">{t('勾选证据只关闭期限类提示；缺失负责人和格式问题仍需要修正文档。新版本不沿用旧版本证据。', 'Evidence clears deadline findings only; owner and format issues still require document corrections. New revisions do not inherit old evidence.')}</p></div>}
    {view === 'diff' && <div className="adv-intel-panel"><h4>{prior ? `v${prior.version} → v${current.version}` : t('初始版本，无前序版本', 'Initial revision, no predecessor')}</h4><p className="adv-intel-note">{t('逐行 LCS 对照，不做法律意义判断。', 'Line-by-line LCS comparison, with no legal interpretation.')} +{differences.filter(item => item.kind === 'added').length} / −{differences.filter(item => item.kind === 'removed').length}</p><div className="adv-intel-diff">{differences.map((item, i) => <pre key={i} className={`adv-intel-diff-${item.kind}`}><b>{item.kind === 'added' ? '+' : item.kind === 'removed' ? '−' : ' '}</b>{item.text}</pre>)}</div></div>}
    {view === 'findings' && <div className="adv-intel-panel"><h4>{t('规则发现与处理流', 'Rule findings and handling flow')}</h4>{findings.length ? findings.map(finding => <article className="adv-intel-finding" key={finding.id}><div><span className={`adv-intel-pill ${finding.severity === 'high' ? 'adv-intel-danger-text' : ''}`}>{finding.severity.toUpperCase()}</span><strong>{labels[finding.code]}</strong><button type="button" onClick={() => source(finding.obligation.line)}>{finding.source}</button></div><p>{finding.obligation.id} · {finding.obligation.description}</p><div className="adv-intel-toolbar"><label>{t('处理状态', 'Handling status')}<select value={handling[finding.id]?.state ?? 'open'} onChange={event => setHandling(items => ({ ...items, [finding.id]: { state: event.target.value, note: items[finding.id]?.note ?? '' } }))}><option value="open">{t('待处理', 'Open')}</option><option value="in-progress">{t('处理中', 'In progress')}</option><option value="recorded">{t('已记录', 'Recorded')}</option></select></label><label className="adv-intel-grow">{t('处理备注', 'Handling note')}<input value={handling[finding.id]?.note ?? ''} maxLength={240} onChange={event => setHandling(items => ({ ...items, [finding.id]: { state: items[finding.id]?.state ?? 'open', note: event.target.value } }))} /></label></div></article>) : <Empty>{t('当前日期与证据状态下，没有规则命中。不是合规或法律认可。', 'No rules match under the current date/evidence state. This is not compliance or legal approval.')}</Empty>}<p className="adv-intel-note">{t('标记已记录不删除规则发现，也不表示义务已履行。', 'Marking a finding recorded does not remove it or imply obligation fulfillment.')}</p></div>}
    {view === 'documents' && <div className="adv-intel-panel"><h4>{current.id}@{current.version} / {t('证据行', 'Source lines')}</h4><div className="adv-intel-contract-source">{current.body.split('\n').map((line, i) => <div key={i} className={focusLine === i + 1 ? 'adv-intel-highlight' : ''}><span>L{i + 1}</span><code>{line}</code></div>)}</div><label>{t('编辑并创建新版本', 'Edit and create a revision')}<textarea rows={9} maxLength={14000} value={draft} onChange={event => setDraft(event.target.value)} /></label><p className="adv-intel-note">OBL|id|YYYY-MM-DD|owner|description<br />PAY|id|YYYY-MM-DD|owner|amount|currency</p><button type="button" className="adv-intel-primary" onClick={save} disabled={documents.length >= 40}>{t('保存为新版本', 'Save new revision')}</button><p className="adv-intel-note" role="status">{notice || t('最多40个版本、每版本200行；保留历史。', 'Up to 40 revisions and 200 lines per revision; history retained.')}</p></div>}
    {view === 'reviews' && <div className="adv-intel-panel"><div className="adv-intel-toolbar"><button type="button" className="adv-intel-primary" onClick={() => setReviews(items => [...items, { version: selected, date: today, findings: findings.length, recorded: findings.filter(item => handling[item.id]?.state === 'recorded').length, evidence: obligations.filter(item => evidence.has(item.key)).length }])}><Check size={14} />{t('保存本版本审阅快照', 'Save revision review snapshot')}</button><button type="button" className="adv-intel-secondary" onClick={() => exportJSON(`clause-${current.id}-v${current.version}.json`, { synthetic: true, noLegalAdvice: true, document: current, simulatedDate: today, obligations, findings, handling, evidence: [...evidence].filter(key => key.startsWith(`${current.id}@${current.version}:`)), reviews })}><ArrowDownToLine size={14} />{t('导出审阅 JSON', 'Export review JSON')}</button></div>{reviews.length ? <div className="adv-intel-table-wrap"><table><thead><tr><th>{t('版本', 'Version')}</th><th>{t('模拟日期', 'Simulated date')}</th><th>{t('发现 / 已记录', 'Findings / recorded')}</th><th>{t('证据', 'Evidence')}</th></tr></thead><tbody>{reviews.map((review, i) => <tr key={i}><td>{review.version}</td><td>{review.date}</td><td>{review.findings} / {review.recorded}</td><td>{review.evidence}</td></tr>)}</tbody></table></div> : <Empty>{t('保存当前审阅结果，让版本与发现数量可追溯。', 'Save a review to trace versions and finding counts.')}</Empty>}</div>}
  </section>;
}

export function AdvancedIntelligenceDemo({ id, locale }: AdvancedDemoProps) {
  if (id === 'research-atlas') return <ResearchAtlas key={`${id}-${locale}`} locale={locale} />;
  if (id === 'model-foundry') return <ModelFoundry key={id} locale={locale} />;
  if (id === 'learning-campus') return <LearningCampus key={id} locale={locale} />;
  if (id === 'contract-desk') return <ContractDesk key={id} locale={locale} />;
  return null;
}
